import json
from itertools import product

def solve_puzzle():
    # Houses indexed 0..5 internally, representing 1..6
    houses = list(range(6))

    # Attributes as per puzzle
    names = ['Alice', 'Arnold', 'Carol', 'Peter', 'Bob', 'Eric']
    phones = ['huawei p50', 'iphone 13', 'xiaomi mi 11', 'oneplus 9', 'samsung galaxy s21', 'google pixel 6']

    # Link constraints between names and phones
    linked = {
        'Alice': 'iphone 13',
        'Eric': 'huawei p50',
        'Arnold': 'oneplus 9'
    }
    phone_to_name = {v: k for k, v in linked.items()}

    # Pre-placed constraints per house (by index)
    fixed_phone_by_house = {
        0: 'huawei p50',     # Clue 2
        2: 'xiaomi mi 11',   # Clue 8
        5: 'oneplus 9',      # Clue 3
    }

    # Forbidden phones in certain houses
    forbidden_phones_by_house = {
        1: set(['google pixel 6', 'iphone 13'])  # Clues 4 and 5
    }

    # Initialize assignment structures
    name_at = [None] * 6
    phone_at = [None] * 6
    used_names = set()
    used_phones = set()

    # Apply fixed phones and propagate linked names from the start
    for h, ph in fixed_phone_by_house.items():
        phone_at[h] = ph
        used_phones.add(ph)
        # If phone implies a specific name, enforce it
        if ph in phone_to_name:
            nm = phone_to_name[ph]
            name_at[h] = nm
            used_names.add(nm)

    def phone_allowed_at(phone, house_idx):
        # Check fixed phone requirement
        if house_idx in fixed_phone_by_house and fixed_phone_by_house[house_idx] != phone:
            return False
        # Check forbidden phones
        if house_idx in forbidden_phones_by_house and phone in forbidden_phones_by_house[house_idx]:
            return False
        return True

    def is_name_possible_at(name, house_idx):
        # If house already has a different name, not possible
        if name_at[house_idx] is not None and name_at[house_idx] != name:
            return False
        # Check name-phone link consistency at the house
        if name in linked:
            req_phone = linked[name]
            # If a phone is already placed here, it must match the required phone
            if phone_at[house_idx] is not None and phone_at[house_idx] != req_phone:
                return False
            # If required phone is already used elsewhere (different house), then this house must be that phone
            # But we also need to ensure the phone is allowed at this house.
            if phone_at[house_idx] is None:
                if req_phone in used_phones:
                    return False
                if not phone_allowed_at(req_phone, house_idx):
                    return False
        else:
            # Name has no specific phone requirement:
            # If the house has a phone that implies a different name, it's impossible.
            if phone_at[house_idx] in phone_to_name and phone_to_name[phone_at[house_idx]] != name:
                return False
            # Otherwise it's possible.
        return True

    def global_partial_check():
        # Clue 6: There is one house between Bob and Carol.
        bob_pos = None
        carol_pos = None
        for i in houses:
            if name_at[i] == 'Bob':
                bob_pos = i
            if name_at[i] == 'Carol':
                carol_pos = i
        if bob_pos is not None and carol_pos is not None:
            if abs(bob_pos - carol_pos) != 2:
                return False
        elif bob_pos is not None:
            # Ensure there is a viable place for Carol two positions away
            possible_js = [j for j in (bob_pos - 2, bob_pos + 2) if 0 <= j < 6]
            any_viable = False
            for j in possible_js:
                if is_name_possible_at('Carol', j):
                    any_viable = True
                    break
            if not any_viable:
                return False
        elif carol_pos is not None:
            # Ensure there is a viable place for Bob two positions away
            possible_js = [j for j in (carol_pos - 2, carol_pos + 2) if 0 <= j < 6]
            any_viable = False
            for j in possible_js:
                if is_name_possible_at('Bob', j):
                    any_viable = True
                    break
            if not any_viable:
                return False

        # Clue 9: Alice is somewhere to the left of Carol.
        alice_pos = None
        carol_pos = None
        for i in houses:
            if name_at[i] == 'Alice':
                alice_pos = i
            if name_at[i] == 'Carol':
                carol_pos = i
        if alice_pos is not None and carol_pos is not None:
            if not (alice_pos < carol_pos):
                return False
        elif alice_pos is not None:
            # Ensure there is a viable place for Carol to the right
            any_viable = False
            for j in range(alice_pos + 1, 6):
                if is_name_possible_at('Carol', j):
                    any_viable = True
                    break
            if not any_viable:
                return False
        elif carol_pos is not None:
            # Ensure there is a viable place for Alice to the left
            any_viable = False
            for j in range(0, carol_pos):
                if is_name_possible_at('Alice', j):
                    any_viable = True
                    break
            if not any_viable:
                return False

        # Clues 4 and 5: Not-in-second-house constraints already enforced in domains, but ensure no violations in partial
        # House 2 index 1
        if phone_at[1] is not None:
            if phone_at[1] in ['google pixel 6', 'iphone 13']:
                return False

        # Clue 1, 7, 10: Linked constraints are enforced on pair checks and initial fixed assignments; also verify consistency
        for i in houses:
            if name_at[i] is not None and name_at[i] in linked:
                req_phone = linked[name_at[i]]
                if phone_at[i] is not None and phone_at[i] != req_phone:
                    return False
            if phone_at[i] is not None and phone_at[i] in phone_to_name:
                req_name = phone_to_name[phone_at[i]]
                if name_at[i] is not None and name_at[i] != req_name:
                    return False

        # Clue 2, 3, 8: fixed positions should remain consistent
        for h, ph in fixed_phone_by_house.items():
            if phone_at[h] is not None and phone_at[h] != ph:
                return False

        return True

    def possible_pairs_for_house(h):
        # Determine candidate names
        if name_at[h] is not None:
            name_candidates = [name_at[h]]
        else:
            name_candidates = [n for n in names if n not in used_names]

        # Determine candidate phones
        if phone_at[h] is not None:
            phone_candidates = [phone_at[h]]
        else:
            phone_candidates = [p for p in phones if p not in used_phones]
            # Apply house-specific phone constraints
            if h in fixed_phone_by_house:
                phone_candidates = [p for p in phone_candidates if p == fixed_phone_by_house[h]]
            if h in forbidden_phones_by_house:
                phone_candidates = [p for p in phone_candidates if p not in forbidden_phones_by_house[h]]

        # Filter by name-phone link consistency
        candidates = []
        for nm, ph in product(name_candidates, phone_candidates):
            ok = True
            if nm in linked and linked[nm] != ph:
                ok = False
            if ph in phone_to_name and phone_to_name[ph] != nm:
                ok = False
            # Additional consistency: if house has a conflicting set already (shouldn't happen due to above)
            if not ok:
                continue
            # Check "Alice left of Carol" feasibility at pair level if it assigns either name
            prev_name = name_at[h]
            prev_phone = phone_at[h]
            # Temporarily assign to test partial global constraints
            name_at[h] = nm
            phone_at[h] = ph
            used_names.add(nm)
            used_phones.add(ph)
            ok = global_partial_check()
            # Revert temporary
            used_names.remove(nm)
            used_phones.remove(ph)
            name_at[h] = prev_name
            phone_at[h] = prev_phone
            if ok:
                candidates.append((nm, ph))
        return candidates

    def select_unassigned_house():
        best_h = None
        best_domain = None
        best_size = None
        for h in houses:
            if name_at[h] is not None and phone_at[h] is not None:
                continue
            domain = possible_pairs_for_house(h)
            size = len(domain)
            if size == 0:
                return h, domain  # dead-end quickly
            if best_h is None or size < best_size:
                best_h = h
                best_domain = domain
                best_size = size
        return best_h, best_domain

    solution = None

    def backtrack():
        nonlocal solution
        # If all assigned:
        if all(name_at[h] is not None and phone_at[h] is not None for h in houses):
            # Final global check
            if global_partial_check():
                solution = [(h, name_at[h], phone_at[h]) for h in houses]
                return True
            return False

        h, domain = select_unassigned_house()
        if h is None:
            return False
        for nm, ph in domain:
            # Save previous
            prev_name = name_at[h]
            prev_phone = phone_at[h]
            already_used_name = nm in used_names
            already_used_phone = ph in used_phones

            # Assign
            name_at[h] = nm
            phone_at[h] = ph
            used_names.add(nm)
            used_phones.add(ph)

            # Continue if globally consistent
            if global_partial_check():
                if backtrack():
                    return True

            # Revert
            name_at[h] = prev_name
            phone_at[h] = prev_phone
            if not already_used_name and nm in used_names:
                used_names.remove(nm)
            if not already_used_phone and ph in used_phones:
                used_phones.remove(ph)

        return False

    # Start search
    backtrack()
    return solution

def main():
    sol = solve_puzzle()
    if sol is None:
        output = {
            "solution": {
                "header": ["House", "name", "phone models"],
                "rows": []
            }
        }
    else:
        # sol is list of tuples (house_idx, name, phone) in order of houses 0..5
        rows = []
        for h, nm, ph in sol:
            rows.append([str(h + 1), nm, ph])
        output = {
            "solution": {
                "header": ["House", "name", "phone models"],
                "rows": rows
            }
        }
    print(json.dumps(output, ensure_ascii=False, indent=2))

if __name__ == "__main__":
    main()
